#include <iostream>
#include <vector>
#include <algorithm>
int main() {
    std::vector<int> v = {1,2,2,3,2,4,5,2};
    std::cout << "count 2 = " << std::count(v.begin(), v.end(), 2) << '\n';
    std::cout << "count_if even = " << std::count_if(v.begin(), v.end(), [](int x){ return x % 2 == 0; }) << '\n';
}
